from pathlib import Path
p=Path(r"C:/Users/dfred/AppData/Local/Temp/s169cw-cap-calc.py")
exec(p.read_text().split('V0=')[0])
H=arb('.005');T=arb('21.25');delta=sum((abs(q[k])*(T*H)**k for k in range(2,7)),arb(0))
U2=2*abs(q[2])*T/(1-delta)
U3=sum((k*abs(q[k])*T**(k-1)*H**(k-3)/(1-delta) for k in range(3,7)),arb(0))
vmax=arb('10.25')*(U2*H**2+U3*H**3)/2
bound=(1-delta)**arb('-2.5')*((1-vmax)**arb('-5.5')+arb('2.75')*(1-vmax)**arb('-6.5'))
# IMPORTANT complex exponent modulus needs phase cost; using |alpha-4|<=.5 adds exp(.5 |log q|+...). Guard 6 replaces tentative 5.
Ct=[arb(1)]+[max(rat(max(abs(a),abs(b))) for a,b in controls[i])/2**i for i in range(1,10)]
Cd=[arb(1)]+[max(rat(max(abs(a),abs(b))) for a,b in controls[i])/4**i for i in range(1,10)]
A=[]
for j in range(5):
 aa=arb(0)
 for i in range(2):
  for k in range(6):
   bb=arb(0)
   for pp in range(j+i+1):
    for qq in range(k+1):bb+=comb(j+i,pp)*comb(k,qq)*Ct[pp]*Cd[qq]*arb(factorial(j+i-pp))/6**(j+i-pp)*arb(factorial(k-qq))/6**(k-qq)
   aa+=arb(comb(5,k)).sqrt()*bb
 A.append(2*arb('59.5').sqrt()*6*aa)
X=S.symbols('X');pol=[]
for n in range(8):pol.append([rat(abs(v)) for v in reversed(S.Poly(S.prod(S.Rational('4.005')+X-j for j in range(n)),X).all_coeffs())])
@lru_cache(None)
def input_norm(k,log):
 out=arb(0)
 for n in range(k+1):
  for i in range(n+1):
   for m,v in enumerate(pol[n-i]):
    if log:val=181*M(i,-n+i)*WL[m]+8*(M(i+1,-n+i)+abs(sig-n+i)*M(i,-n+i-1))*W[m]
    else:val=arb(3).sqrt()*M(i,-n+i)*W[m]
    out+=arb(comb(k,n)).sqrt()*comb(n,i)*v*val
 return out
cs=[[arb(1)]]
for ell in range(1,4):cs.append([(5+j-sig)*(cs[-1][j] if j<ell else 0)+(cs[-1][j-1] if j else 0) for j in range(ell+1)])
def geo(p):
 rr=arb(2)**(-p);sp=H**p/(1-rr)
 return sp,sp*((1/H).log()+arb(2).log()*rr/(1-rr))
sp=U2*geo(2)[0]+U3*geo(3)[0];sl=U2*geo(2)[1]+U3*geo(3)[1]
eta=arb(0);by=[]
for ell in range(4):
 for rr in range(ell+1):
  r=rr+1;outer=100*arb(comb(3,ell)).sqrt()*cs[ell][rr]*2**(4+r-sig)
  val=arb(0)
  for j in range(r+1):val+=comb(r,j)*A[j]*(7*input_norm(3+r-j,True)*sp+input_norm(3+r-j,False)*(28*sp+4*sl))
  eta+=outer*val
print(json.dumps(dict(coordinate_near_candidate=old.encoded(K*eta),delta=old.encoded(delta),U2=old.encoded(U2),U3=old.encoded(U3),vmax=old.encoded(vmax),real_exponent_guard=old.encoded(bound),amplitude=[old.encoded(x) for x in A],scope='constant-coefficient near coordinate component only; pending full matching and return'),indent=2))
